import React, { useState } from 'react';
import './styles.css';

const QUESTIONS = [
  { question: '2+3 等于多少？', options: ['4', '5', '6'], answer: '5' },
  { question: '水的化学式是什么？', options: ['H2O', 'CO2', 'O2'], answer: 'H2O' },
  { question: '一周有几天？', options: ['5', '6', '7'], answer: '7' },
];

export default function App() {
  const [current, setCurrent] = useState(0);
  const [selected, setSelected] = useState(null);
  const [submitted, setSubmitted] = useState(false);

  const q = QUESTIONS[current];
  const isCorrect = selected === q.answer;

  function handleSelect(opt) {
    if (submitted) return;
    setSelected(opt);
  }

  function handleSubmit() {
    if (selected === null || submitted) return;
    setSubmitted(true);
  }

  return (
    <main className="quiz">
      <p className="progress" data-testid="progress">
        第 {current + 1} 题 / 共 {QUESTIONS.length} 题
      </p>
      <h1 className="question" data-testid="question">{q.question}</h1>
      <div className="options" role="radiogroup">
        {q.options.map((opt) => (
          <button
            key={opt}
            type="button"
            role="radio"
            aria-checked={selected === opt ? 'true' : 'false'}
            data-testid="option"
            className={'option' + (selected === opt ? ' selected' : '')}
            onClick={() => handleSelect(opt)}
          >
            {opt}
          </button>
        ))}
      </div>
      <button
        type="button"
        data-testid="submit"
        className="submit"
        disabled={selected === null || submitted}
        onClick={handleSubmit}
      >
        提交
      </button>
      {submitted && (
        <div className="feedback-area">
          <p className="feedback" data-testid="feedback">
            {isCorrect ? '回答正确' : '回答错误'}
          </p>
          <p className="correct-answer" data-testid="correct-answer">
            正确答案：{q.answer}
          </p>
        </div>
      )}
    </main>
  );
}

